        iscale.set_scaling_factor(m.fs.brine_feed.properties[0.0].flow_mol_phase_comp["Liq","K"], 9E+03 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_feed.properties[0.0].flow_mol_phase_comp["Liq","Mg"], 5E+01 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_feed.properties[0.0].flow_mol_phase_comp["Liq","Li"], 4E+00 / reference_li * mol_flow_li)
