        iscale.set_scaling_factor(m.fs.brine_storage.surge_capacity[0.0], 1.000E+00 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_storage.tank_volume[0.0], 4E-01 / reference_li * mol_flow_li)
