        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","Mg"], 5E+01 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","Li"], 4E+00 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","Ca"], 3E+03 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","Cl"], 4E+00 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","SO4"], 2E+04 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","B"], 6E+01 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","H"], 1E+08 / reference_li * mol_flow_li)
        iscale.set_scaling_factor(m.fs.brine_pump.control_volume.properties_out[0.0].flow_mol_phase_comp["Liq","HCO3"], 2E+04 / reference_li * mol_flow_li)
